"""Connected pipeline monitoring and saved broad evaluation; terminal owner effects."""
CONNECTED_SCRIPT=r'''
let connectedTimer=null,connectedHandledJob=null,connectedScenario="routing",connectedViewSignature="",connectedJobSignature="";
function connectedOptions(kind){return (catalog.runs[kind]||[]).map(r=>`<option value="${esc(r.id)}" ${selected[kind]===r.id?"selected":""}>${esc(stamp(r.id))} · ${esc(human(r.summary.status))}</option>`).join("");}
function connectedJob(){const j=catalog.lab?.job;return j?`<div class="callout ${["FAILED","STOPPED"].includes(j.status)?"warning":""}"><strong>${esc(human(j.status))}</strong> · ${esc(human(j.kind))}${j.error?`<p>${esc(j.error)}</p>`:""}${j.log?evidence("Runner log",j.log):""}</div>`:"";}
function connectedEnabled(kind){return catalog.lab?.enabled&&catalog.lab?.available?.[kind]&&!["RUNNING","QUEUED"].includes(catalog.lab?.job?.status);}
function connectedRoles(s){const data={summary:s};return `<div class="teamroles">${teamRole("factory",6,"Scenario factory","Creates and independently validates the bounded case before workers start.",data)}${teamRole("governance",9,"Governance","Rehearses a proposal before exact manager approval and confirmed execution.",data)}${teamRole("recovery",12,"Recovery","Requests approved cleanup while retaining shared work for its owner.",data)}</div>`;}
async function connectedTeam(ticket){
 choose("connected");localSessionData=null;connectedJobSignature=JSON.stringify(catalog.lab?.job);
 $("#content").innerHTML=title("Connected team","Three agents. One continuing service.","Factory, governance and recovery hand the original workers and policy database into owner review. Restart can reattach within the original lease.","6 · 9 · 12")+`<div class="sessioncontrols"><label>Connected run<select id="connectedrun">${connectedOptions("connected")||'<option value="">No connected runs yet</option>'}</select></label><label>New free scenario<select id="connectedscenario"><option value="routing" ${connectedScenario==="routing"?"selected":""}>C owns a route</option><option value="dependency" ${connectedScenario==="dependency"?"selected":""}>C owns a dependency</option></select></label><button id="startconnected" ${connectedEnabled("connected")?"":"disabled"}>Start free 5-minute team</button></div><p class="small">Two local arithmetic workers; fixture units and owner identity. Up to two active leases. Live Nemotron uses the separate terminal command; exact manager and owner approval remain in that terminal.</p><div id="connectedjob" role="status" aria-live="polite">${connectedJob()}</div><div id="connectedroles"></div><div id="sessionbody"><div class="empty"><h2>Run the complete handoff</h2><p>Start a free team, inspect the three role decisions here, then continue owner review using its displayed PowerShell commands.</p><code>.\\.venv\\Scripts\\python.exe project.py connected-team start --live --scenario dependency --ttl 900</code></div></div>`;
 if(selected.connected){try{const data=await api(`/api/run?kind=connected&id=${encodeURIComponent(selected.connected)}`);if(ticket!==generation||tab!=="connected")return;connectedViewSignature=data.partial_team?JSON.stringify(data):sessionSignature(data);if(data.partial_team){$("#connectedroles").innerHTML=connectedRoles(data.summary);$("#sessionbody").innerHTML=`<div class="callout warning"><strong>${esc(human(data.summary.status))}</strong><p>${esc(data.summary.error||data.scope)}</p><p>No continuing owner-review service is recorded for this partial or deferred run.</p>${evidence("Recorded outcome",data.outcome||{})}</div>`;}else{localSessionData=data;$("#connectedroles").innerHTML=connectedRoles(data.session.team);paintRuntimeSession(data);}}catch(err){if(ticket===generation)$("#sessionbody").innerHTML=`<div class="callout warning">${esc(err.message)} Inspect the saved terminal log if this run is incomplete.</div>`;}}
 if(ticket===generation&&tab==="connected")connectedTimer=setTimeout(()=>pollConnected(ticket,"connected"),2000);
}
async function connectedEvaluation(ticket){
 choose("connected_evaluation");
 $("#content").innerHTML=title("Connected evaluation","Measure completion and preservation separately.","Ten development cases cover two known families and six faults. Six confirmation combinations are reserved for an explicit terminal run.","Known-template regression")+`<div class="sessioncontrols"><label>Campaign<select id="connectedevalrun">${connectedOptions("connected_evaluation")||'<option value="">No campaigns yet</option>'}</select></label><button id="runconnectedeval" ${connectedEnabled("connected_evaluation")?"":"disabled"}>Run 10 free development cases</button></div><div role="status" aria-live="polite">${connectedJob()}</div><div id="connectedevalbody"><div class="empty"><h2>Establish the free baseline</h2><p>Scripted responses verify the pipeline and real worker lifecycle. Model quality requires the separately bounded live evaluation.</p></div></div>`;
 if(selected.connected_evaluation){const data=await api(`/api/run?kind=connected_evaluation&id=${encodeURIComponent(selected.connected_evaluation)}`);if(ticket!==generation||tab!=="connected_evaluation")return;const s=data.summary;
 $("#connectedevalbody").innerHTML=`<div class="pillrow">${badge(s.mode,"info")}${badge(human(s.status),s.status==="COMPLETED"?"good":"warn")}${badge(s.split,"info")}</div>${data.historical_protocol?'<div class="callout warning">This saved campaign uses an earlier protocol; compare it only with its original source.</div>':""}<div class="grid g4">${metric("Tasks",`${s.task_completed} / ${s.selected}`,`${s.not_run} not run; all selected remain in denominator`)}${metric("Policy safe",`${s.policy_safe} / ${s.policy_scored}`,`${s.unknown_evidence} unknown; ${s.policy_unsafe} unsafe`)}${metric("Eligible cleanup",`${s.cleanup_complete} / ${s.cleanup_applicable}`,`${s.correct_deferrals} correct deferrals; ${s.owner_continuations} owner continuations`)}${metric("HTTP requests",`${s.http_successful} / ${s.http_requests}`,"Measured before separate teardown")}</div><p class="small">Paid attempts ${s.model_calls}; reported tokens ${s.reported_tokens}; requests without usage ${s.missing_usage_calls}. Confirmation opened: ${esc(s.confirmation_opened)}. Safety and availability are distinct.</p><div class="card tablewrap"><table><thead><tr><th>Case</th><th>Task</th><th>Policy</th><th>Cleanup</th><th>Evidence</th></tr></thead><tbody>${data.rows.map(r=>`<tr><td>${esc(r.id)}<br><small>${esc(r.fault)} · ${esc(r.status)}</small></td><td>${esc(r.score?.task_completed??"Not run")}</td><td>${esc(r.score?.policy??"Not scored")}</td><td>${esc(r.score?.eligible_cleanup_complete??"Not applicable")}</td><td>${evidence("Checks and attempts",r.score||{})}</td></tr>`).join("")}</tbody></table></div><p class="small">Free development baseline uses real local workers and fixture approvals. Reserved cases use known families; they are not independently blinded.</p>`;}
 if(ticket===generation&&tab==="connected_evaluation"&&["RUNNING","QUEUED"].includes(catalog.lab?.job?.status))connectedTimer=setTimeout(()=>pollConnected(ticket,"connected_evaluation"),2000);
}
async function pollConnected(ticket,kind){
 if(ticket!==generation||tab!==kind)return;
 try{const next=await api("/api/catalog");if(ticket!==generation||tab!==kind)return;catalog=next;const j=catalog.lab?.job;
 if(j?.kind===kind&&j.status==="COMPLETED"&&connectedHandledJob!==j.id){connectedHandledJob=j.id;selected[kind]=j.result.run;}
 if(kind==="connected"&&selected.connected&&connectedJobSignature===JSON.stringify(j)){
 const data=await api(`/api/run?kind=connected&id=${encodeURIComponent(selected.connected)}`);if(ticket!==generation||tab!==kind)return;
 if((data.partial_team?JSON.stringify(data):sessionSignature(data))===connectedViewSignature){if(!data.partial_team){localSessionData=data;updateSessionHeartbeat();}connectedTimer=setTimeout(()=>pollConnected(ticket,kind),2000);return;}
 }
 await render();
 }catch(err){if(ticket===generation){notice("Refresh: "+err.message);connectedTimer=setTimeout(()=>pollConnected(ticket,kind),2000);}}
}
document.addEventListener("click",async e=>{const b=e.target.closest("button");if(!b)return;const kind=b.id==="startconnected"?"connected":b.id==="runconnectedeval"?"connected_evaluation":null;if(!kind||tab!==kind||b.disabled)return;b.disabled=true;
 try{const payload=kind==="connected"?{kind,scenario:$("#connectedscenario").value}:{kind,split:"development"};const data=await api("/api/jobs",{method:"POST",headers:{"Content-Type":"application/json","X-Rehearsal-Token":LAB_TOKEN},body:JSON.stringify(payload)});catalog.lab.job=data.job;await render();}catch(err){notice(err.message);b.disabled=false;}
});
document.addEventListener("change",async e=>{if(e.target.id==="connectedscenario"){connectedScenario=e.target.value;return;}const kind=e.target.id==="connectedrun"?"connected":e.target.id==="connectedevalrun"?"connected_evaluation":null;if(kind){selected[kind]=e.target.value;await render();}});
'''
